  const oldIdx = new Int32Array(len + 1);
  const newIdx = new Int32Array(len + 1);
  for (let i = 0; i < len; i++) {
    oldIdx[i + 1] = oldIdx[i] + (ops[i].op !== 'insert' ? 1 : 0);
    newIdx[i + 1] = newIdx[i] + (ops[i].op !== 'delete' ? 1 : 0);
  }

  const hunks = [];
  let i = 0;
  while (i < len) {
    if (ops[i].op === 'equal') {
      i++;
      continue;
    }
    // Group changes separated by gaps of at most 2 * context unchanged lines.
    let end = i + 1; // exclusive end of the last change in this group
    let j = end;
    while (j < len) {
      if (ops[j].op !== 'equal') {
        end = j + 1;
        j++;
        continue;
      }
      let k = j;
      while (k < len && ops[k].op === 'equal') k++;
      if (k === len || k - j > 2 * context) break;
      j = k;
    }
    // Up to `context` equal lines before the first and after the last change.
    let back = 0;
    while (back < context && ops[i - back - 1] !== undefined && ops[i - back - 1].op === 'equal') {
      back++;
    }
    const start = i - back;
    let after = 0;
    while (after < context && end + after < len && ops[end + after].op === 'equal') {
      after++;
    }
    const hend = end + after;

    const lines = [];
    let oldLines = 0;
    let newLines = 0;
    for (let t = start; t < hend; t++) {
      const op = ops[t];
      if (op.op === 'equal') {
        lines.push(' ' + op.line);
        oldLines++;
        newLines++;
      } else if (op.op === 'delete') {
        lines.push('-' + op.line);
        oldLines++;
      } else {
        lines.push('+' + op.line);
        newLines++;
      }
    }
    hunks.push({
      oldStart: oldLines === 0 ? oldIdx[start] : oldIdx[start] + 1,
      oldLines,
      newStart: newLines === 0 ? newIdx[start] : newIdx[start] + 1,
      newLines,
      lines,
    });
    i = hend;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const out = [];
  let oldPos = 0; // lines of a consumed so far
  for (let idx = 0; idx < hunks.length; idx++) {
    const fail = () => {
      throw new Error(`hunk ${idx} does not apply`);
    };
    const hunk = hunks[idx];
    if (hunk === null || typeof hunk !== 'object' || !Array.isArray(hunk.lines)) fail();
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (
      !Number.isInteger(oldStart) || !Number.isInteger(oldLines) ||
      !Number.isInteger(newStart) || !Number.isInteger(newLines) ||
      oldLines < 0 || newLines < 0
    ) {
      fail();
    }
    let oldCount = 0;
    let newCount = 0;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) fail();
      const prefix = line.charCodeAt(0);
      if (prefix === 32) { // ' '
        oldCount++;
        newCount++;
      } else if (prefix === 45) { // '-'
        oldCount++;
      } else if (prefix === 43) { // '+'
        newCount++;
      } else {
        fail();
      }
    }
    if (oldCount !== oldLines || newCount !== newLines) fail();

    // Position in a (lines consumed) where this hunk starts.
    const oldPosH = oldLines === 0 ? oldStart : oldStart - 1;
    const newPosH = newLines === 0 ? newStart : newStart - 1;
    if (oldPosH < 0 || oldPosH > a.length || newPosH < 0) fail();
    if (oldPosH < oldPos) fail(); // overlapping or out-of-order hunks

    // Retain unmentioned original lines before this hunk.
    for (let t = oldPos; t < oldPosH; t++) out.push(a[t]);
    if (out.length !== newPosH) fail(); // new coordinates disagree

    let t = oldPosH;
    for (const line of lines) {
      const prefix = line[0];
      if (prefix === '+') {
        out.push(line.slice(1));
        continue;
      }
      if (t >= a.length || a[t] !== line.slice(1)) fail();
      if (prefix === ' ') out.push(a[t]);
      t++;
    }
    oldPos = t;
  }
  for (let t = oldPos; t < a.length; t++) out.push(a[t]);
  return out;
}

module.exports = { diffLines, unifiedHunks, applyHunks };
